(ns finfolkbuild.db.publication
  (:require [finfolkdb.main.scaffold-000-dev]
            [finfolkdb.rpc.api-group-member :as rpc]
            [finfolkdb.fn.site.catalog :as sites]
            [finfolkdb.fn.directory.operations :as directory]
            [finfolkdb.fn.events.operations :as events]
            [lang.core.compile :as compile]
            [std.make.compile :as make]
            [std.json :as json]))
(def PRIVILEGES "ALTER FUNCTION finfolk_rpc.member_permitted(boolean) SET search_path=pg_catalog;\nALTER FUNCTION finfolk_rpc.auth_identity(text) SET search_path=pg_catalog;\nREVOKE ALL ON FUNCTION finfolk_rpc.auth_identity(text) FROM PUBLIC;\nREVOKE ALL ON FUNCTION finfolk_rpc.actor_id(),finfolk_rpc.member_permitted(boolean) FROM PUBLIC;\nREVOKE ALL ON FUNCTION finfolk_rpc.member_profile() FROM PUBLIC;\nREVOKE ALL ON FUNCTION finfolk_rpc.profile_save(jsonb),finfolk_rpc.checkin_record(text) FROM PUBLIC;\nDO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='finfolk_api') THEN\nGRANT USAGE ON SCHEMA finfolk_rpc TO finfolk_api;\nGRANT EXECUTE ON FUNCTION finfolk_rpc.auth_identity(text),finfolk_rpc.actor_id(),finfolk_rpc.member_permitted(boolean),finfolk_rpc.member_profile(),finfolk_rpc.profile_save(jsonb),finfolk_rpc.checkin_record(text) TO finfolk_api;\nEND IF; END $$;\n")
(defn sql []
  (let [[_ content] (binding [make/*mock-compile* true]
                      (compile/compile-module-schema
                       {:lang :postgres :main 'finfolkdb.main.scaffold-000-dev :output "pilot.sql"
                        :emit {:code {:label {:line-number? false}}}}))]
    (str "-- Generated by scripts/generate_db.mjs from finfolkdb source declarations.\nCREATE SCHEMA IF NOT EXISTS finfolk_rpc;\n" content "\n" PRIVILEGES "\n" sites/SQL "\n" directory/SQL "\n" events/SQL)))
(defn contracts []
  (json/write (into {} (map (fn [[k v]] [(name k) (update v :function str)]) (merge rpc/OPERATIONS directory/OPERATIONS events/OPERATIONS)))))
